import React, { useEffect, useState } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:3000';

interface Machine {
  id: number;
  name: string;
  status: string;
  production: number;
  temperature: number;
}

interface Alert {
  id: number;
  machine: string;
  type: string;
  message: string;
}

const styles: Record<string, React.CSSProperties> = {
  app: { minHeight: '100vh', backgroundColor: '#0f172a', color: '#f1f5f9', padding: '24px', fontFamily: 'sans-serif' },
  header: { marginBottom: '32px' },
  title: { fontSize: '28px', fontWeight: 'bold', color: '#60a5fa' },
  subtitle: { color: '#94a3b8', marginTop: '4px' },
  grid: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '16px', marginBottom: '32px' },
  card: { backgroundColor: '#1e293b', borderRadius: '12px', padding: '20px' },
  cardLabel: { color: '#94a3b8', fontSize: '14px' },
  cardValue: { fontSize: '36px', fontWeight: 'bold', marginTop: '4px' },
  section: { backgroundColor: '#1e293b', borderRadius: '12px', padding: '24px', marginBottom: '24px' },
  sectionTitle: { fontSize: '18px', fontWeight: '600', marginBottom: '16px' },
  machineRow: { backgroundColor: '#0f172a', borderRadius: '8px', padding: '16px', marginBottom: '8px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  machineName: { fontWeight: '500' },
  machineInfo: { color: '#94a3b8', fontSize: '13px', marginTop: '4px' },
  badge: { padding: '4px 10px', borderRadius: '999px', fontSize: '12px', fontWeight: '500', color: 'white' },
  alertRow: { backgroundColor: '#0f172a', borderRadius: '8px', padding: '16px', marginBottom: '8px' },
};

const statusColor: Record<string, string> = {
  operando: '#22c55e',
  manutenção: '#eab308',
  falha: '#ef4444',
};

function App() {
  const [machines, setMachines] = useState<Machine[]>([]);
  const [alerts, setAlerts] = useState<Alert[]>([]);

  useEffect(() => {
    axios.get(`${API_URL}/api/machines`).then(res => setMachines(res.data));
    axios.get(`${API_URL}/api/alerts`).then(res => setAlerts(res.data));
  }, []);

  const operando = machines.filter(m => m.status === 'operando').length;
  const falha = machines.filter(m => m.status === 'falha').length;
  const manutencao = machines.filter(m => m.status === 'manutenção').length;

  return (
    <div style={styles.app}>
      <div style={styles.header}>
        <h1 style={styles.title}>⚙️ SmartFactory Dashboard</h1>
        <p style={styles.subtitle}>Monitoramento Industrial em Tempo Real</p>
      </div>

      <div style={styles.grid}>
        <div style={styles.card}>
          <p style={styles.cardLabel}>Operando</p>
          <p style={{...styles.cardValue, color: '#22c55e'}}>{operando}</p>
        </div>
        <div style={styles.card}>
          <p style={styles.cardLabel}>Em Falha</p>
          <p style={{...styles.cardValue, color: '#ef4444'}}>{falha}</p>
        </div>
        <div style={styles.card}>
          <p style={styles.cardLabel}>Manutenção</p>
          <p style={{...styles.cardValue, color: '#eab308'}}>{manutencao}</p>
        </div>
      </div>

      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>🏭 Máquinas</h2>
        {machines.map(machine => (
          <div key={machine.id} style={styles.machineRow}>
            <div>
              <p style={styles.machineName}>{machine.name}</p>
              <p style={styles.machineInfo}>Temp: {machine.temperature}°C | Produção: {machine.production}%</p>
            </div>
            <span style={{...styles.badge, backgroundColor: statusColor[machine.status] || '#6b7280'}}>
              {machine.status}
            </span>
          </div>
        ))}
      </div>

      <div style={styles.section}>
        <h2 style={styles.sectionTitle}>🚨 Alertas Recentes</h2>
        {alerts.map(alert => (
          <div key={alert.id} style={styles.alertRow}>
            <p style={styles.machineName}>{alert.machine}</p>
            <p style={styles.machineInfo}>{alert.message}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
